/**
 * @name Trace data flow to exec in decorators.py
 * @description Identifies the function parameters that flow into the exec call in decorators.py
 * @kind path-problem
 * @problem.severity error
 * @id py/wrapt/exec-dataflow
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ExecFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode exec |
      exec = API::builtin("exec").getACall() and
      exec.getLocation().getFile().getShortName() = "decorators.py" and
      sink = exec.getArg(0)
    )
  }
}

module ExecFlow = TaintTracking::Global<ExecFlowConfig>;
import ExecFlow::PathGraph

from ExecFlow::PathNode source, ExecFlow::PathNode sink
where ExecFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Data flows from parameter $@ to exec.", source.getNode(), source.getNode().toString()

/**
 * @name Code Injection in decorators.py
 * @description Traces flow from function parameters to exec() calls in decorators.py
 * @kind path-problem
 * @problem.severity error
 * @id py/wrapt/exec-injection
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ExecInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode p |
      p = source and
      p.getScope().getEnclosingModule().getName().matches("wrapt.%")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("exec").getACall() and
      sink = call.getArg(0)
    )
  }
}

module ExecInjectionFlow = TaintTracking::Global<ExecInjectionConfig>;
import ExecInjectionFlow::PathGraph

from ExecInjectionFlow::PathNode source, ExecInjectionFlow::PathNode sink
where ExecInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection from $@.", source.getNode(), "parameter"
